{
  "nl": {
    "issue": [
      {
        "text": "承揽合同的界定与承揽工作类型，以及承揽人亲自完成主要工作、交付工作成果、妥善保管材料与成果的义务",
        "rules": ["c770-1", "c770-2", "c772-1", "c772-2a", "c780-1", "c784-1", "c784-2"]
      },
      {
        "text": "定作人未支付报酬或材料费等价款时承揽人的留置权与拒绝交付权，以及定作人的任意解除权",
        "rules": ["c783-lien", "c783-refuse", "c787-1", "c787-2"]
      },
      {
        "text": "定作人不履行协助义务、工作成果不符合质量要求、报酬支付期限不明时的处理",
        "rules": ["c778-1", "c778-2", "c778-3", "c781", "c782-1", "c782-2", "c782-3", "c780-2"]
      }
    ],
    "conditions": [
      {
        "text": "承揽人按照定作人的要求完成工作、交付工作成果，定作人支付报酬",
        "rules": ["c770-1"]
      },
      {
        "text": "承揽工作属于加工、定作、修理、复制、测试、检验等工作",
        "rules": ["c770-2"]
      },
      {
        "text": "承揽工作需要定作人协助",
        "rules": ["c778-1"]
      },
      {
        "text": "定作人不履行协助义务致使承揽工作不能完成",
        "rules": ["c778-2", "c778-3"]
      },
      {
        "text": "承揽人将承揽的主要工作交由第三人完成",
        "rules": ["c772-2a", "c772-2b"]
      },
      {
        "text": "承揽人完成工作",
        "rules": ["c780-1"]
      },
      {
        "text": "工作成果已交付定作人",
        "rules": ["c780-2"]
      },
      {
        "text": "承揽人交付的工作成果不符合质量要求",
        "rules": ["c781"]
      },
      {
        "text": "对支付报酬的期限没有约定或者约定不明确，且依据第510条仍不能确定",
        "rules": ["c782-2", "c782-3"]
      },
      {
        "text": "定作人未向承揽人支付报酬或者材料费等价款",
        "rules": ["c783-lien", "c783-refuse"]
      }
    ],
    "exceptions": [
      {
        "text": "当事人另有约定的，承揽人无须以自己的设备、技术和劳力完成主要工作",
        "rules": ["c772-1"]
      },
      {
        "text": "当事人另有约定（如约定排除留置权）的，承揽人不享有留置权或拒绝交付的权利",
        "rules": ["c783-lien", "c783-refuse"]
      },
      {
        "text": "承揽人将主要工作交由第三人完成未经定作人同意的，定作人可以解除合同",
        "rules": ["c772-2b"]
      },
      {
        "text": "定作人在承揽人完成工作前可以随时解除合同",
        "rules": ["c787-1"]
      }
    ],
    "effects": [
      {
        "text": "承揽人将主要工作交由第三人完成的，应当就该第三人完成的工作成果向定作人负责",
        "rules": ["c772-2a"]
      },
      {
        "text": "定作人不履行协助义务致使承揽工作不能完成的，承揽人可以催告其在合理期限内履行并顺延履行期限；定作人逾期不履行的，承揽人可以解除合同",
        "rules": ["c778-2", "c778-3"]
      },
      {
        "text": "承揽人完成工作的，应当交付工作成果并提交必要的技术资料和有关质量证明；定作人应当验收该工作成果",
        "rules": ["c780-1", "c780-2"]
      },
      {
        "text": "工作成果不符合质量要求的，定作人可以合理选择请求修理、重作、减少报酬、赔偿损失等违约责任",
        "rules": ["c781"]
      },
      {
        "text": "定作人应当按照约定的期限支付报酬；期限不明且依第510条不能确定的，于交付工作成果时支付，工作成果部分交付的相应支付",
        "rules": ["c782-1", "c782-2", "c782-3"]
      },
      {
        "text": "定作人未支付报酬或者材料费等价款时，承揽人对完成的工作成果享有留置权，或者有权拒绝交付",
        "rules": ["c783-lien", "c783-refuse"]
      },
      {
        "text": "承揽人应当妥善保管定作人提供的材料以及完成的工作成果；因保管不善造成毁损、灭失的，应当承担赔偿责任",
        "rules": ["c784-1", "c784-2"]
      },
      {
        "text": "定作人在承揽人完成工作前可以随时解除合同，造成承揽人损失的，应当赔偿损失",
        "rules": ["c787-1", "c787-2"]
      }
    ],
    "priority": [
      {
        "text": "定作人未付报酬或材料费等价款时，承揽人的拒绝交付权排除第780条的交付工作成果义务",
        "rules": ["c783-refuse"]
      },
      {
        "text": "定作人于承揽人完成工作前随时解除合同的，承揽人不再负交付工作成果的义务",
        "rules": ["c787-1"]
      }
    ],
    "distinguish": [
      {
        "text": "第771条关于承揽合同内容（标的、数量、质量、报酬、承揽方式、材料提供、履行期限、验收标准和方法等）的规定为提示性规定，不产生独立规则",
        "rules": []
      },
      {
        "text": "笔记所列共同承揽人连带责任、保密义务、接受定作人监督检查等义务，本行挂载法条未作规定，不写规则",
        "rules": []
      },
      {
        "text": "笔记强调留置权为法定担保物权，无须当事人特别约定，但可依第783条但书约定排除",
        "rules": ["c783-lien"]
      },
      {
        "text": "承揽合同区别于雇佣、买卖、委托合同：以依定作人要求完成并交付特定工作成果为目的，而非单纯提供劳务或交付现存物品",
        "rules": ["c770-1"]
      }
    ]
  },
